from .money import _from_cents, _parse_cents, format_amount


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("Amounts must be a list")

    total_cents = 0
    for item in amounts:
        total_cents += _parse_cents(item)
        if total_cents > 100000000:
            raise ValueError("Invoice total must be at most 1000000.00")
    return {"total": format_amount(_from_cents(total_cents)), "count": len(amounts)}

