import re
from decimal import Decimal


_AMOUNT_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")
_MAX_AMOUNT = Decimal("1000000.00")


def _parse_cents(value):
    """Validate an amount and return exact integer cents, without context arithmetic."""
    if isinstance(value, bool):
        raise ValueError("Invalid amount type")
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, str) and _AMOUNT_PATTERN.fullmatch(value):
        amount = Decimal(value)
    else:
        raise ValueError("Invalid amount type or syntax")

    if not amount.is_finite() or amount <= 0 or amount > _MAX_AMOUNT:
        raise ValueError("Amount must be positive and at most 1000000.00")

    _, digits, exponent = amount.as_tuple()
    shift = exponent + 2
    if shift < 0:
        fractional_digits = -shift
        if fractional_digits >= len(digits) or any(digits[-fractional_digits:]):
            raise ValueError("Amount must be exactly representable in cents")
        digits = digits[:-fractional_digits]
        shift = 0

    cents = 0
    for digit in digits:
        cents = cents * 10 + digit
    return cents * 10 ** shift


def _from_cents(cents):
    # Tuple construction is exact and does not consult the decimal context.
    return Decimal((0, tuple(int(digit) for digit in str(cents)), -2))


def parse_amount(value):
    return _from_cents(_parse_cents(value))


def format_amount(value):
    return format(value, ".2f")
